.hero__visual::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, #F5FAFE 0%, rgb(245 250 254 / 87%) 6%, rgb(245 250 254 / 0%) 29%); pointer-events: none; }
.service-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }
.service-card { min-width: 0; overflow: hidden; border: 1px solid var(--color-border); border-radius: var(--radius-sm); background: var(--color-surface); box-shadow: var(--shadow-card); transition: box-shadow var(--transition-fast), border-color var(--transition-fast); }
.service-card__image { width: 100%; aspect-ratio: 2.68; object-fit: cover; }
.service-card__title { min-height: 50px; display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 14px; color: var(--color-heading); font-size: 14px; line-height: 1.25; font-weight: 600; }
.service-card:hover { border-color: #ADCDF8; box-shadow: var(--shadow-hover); }
.lead-panel { position: relative; display: grid; grid-template-columns: 36% 42% 22%; min-height: 268px; overflow: hidden; border-radius: var(--radius-lg); background: var(--color-surface-soft); }
.directions-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.button-primary { border: 1px solid var(--color-primary); border-radius: var(--radius-xs); color: #FFF; background: linear-gradient(var(--color-primary-top), var(--color-primary-bottom)); min-height: 44px; padding: 11px 20px; font-size: 14px; font-weight: 600; cursor: pointer; }
.button-primary:hover { background: var(--color-primary-hover); }
@media (max-width: 1023px) {
 .service-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
 .hero__copy { width: 58%; }
 .lead-panel { grid-template-columns: 52% 48%; }
 .lead-panel__benefits { grid-column: 1 / -1; }
}
@media (max-width: 639px) {
 :root { --page-gutter: 20px; }
 .hero { min-height: 0; }
 .hero__copy { width: 100%; }
 .hero__inner { padding-block: 30px 24px; }
 .hero__visual { position: relative; z-index: auto; width: 100%; height: 220px; }
 .hero__visual::after { background: linear-gradient(#F5FAFE, transparent 24%); }
 .service-grid { grid-template-columns: 1fr; }
 .directions-grid, .lead-panel { grid-template-columns: 1fr; }
 .lead-panel__benefits { grid-column: auto; }
 input, select, textarea { font-size: 16px; }
}
@media (prefers-reduced-motion: reduce) {
 html { scroll-behavior: auto; }
 *, *::before, *::after { animation: none !important; transition: none !important; }
}
